export type TreatmentPackageItemKind = typeof TreatmentPackageItemKindConsultation | typeof TreatmentPackageItemKindProcedure | typeof TreatmentPackageItemKindMedicine | typeof TreatmentPackageItemKindExaminationType | typeof TreatmentPackageItemKindVaccine | typeof TreatmentPackageItemKindCheckupType | typeof TreatmentPackageItemKindMerchandiseItem | typeof TreatmentPackageItemKindManualOther;

